"""Cross-check with template forms ({{ }} expressions and random tokens)."""
import hashlib
import json
import random
import subprocess
import sys

sys.path.insert(0, '/tmp/h3/ref')
import fuzz as base
from replay import simulate
import http as refhttp

PROG = ['python3', '-B', 'main.py']


def pybytes(data):
    out = ['b"']
    for byte in data:
        ch = chr(byte)
        if ch in '"\\':
            out.append('\\' + ch)
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\t':
            out.append('\\t')
        elif 0x20 <= byte <= 0x7e:
            out.append(ch)
        else:
            out.append('\\x%02x' % byte)
    out.append('"')
    return ''.join(out)


def token(seed, coord, occ):
    return hashlib.sha256(('%s/%s/%d' % (seed, coord, occ)).encode()).hexdigest()[:20].encode()


def resolve(data, seed, coord):
    if data.startswith('{{') and data.endswith('}}'):
        source = data[2:-2].strip()
        assert source.startswith('b"') and source.endswith('"'), source
        body = source[2:-1]
        out = bytearray()
        i = 0
        while i < len(body):
            ch = body[i]
            if ch == '\\':
                nxt = body[i + 1]
                if nxt == 'r':
                    out.append(13)
                elif nxt == 'n':
                    out.append(10)
                elif nxt == 't':
                    out.append(9)
                elif nxt == '\\':
                    out.append(92)
                elif nxt == '"':
                    out.append(34)
                elif nxt == 'x':
                    out.append(int(body[i + 2:i + 4], 16))
                    i += 4
                    continue
                else:
                    raise AssertionError(nxt)
                i += 2
            else:
                out.append(ord(ch))
                i += 1
        return bytes(out)
    pieces = data.split('<<random_string>>')
    out = bytearray()
    last = len(pieces) - 1
    for index, piece in enumerate(pieces):
        out += piece.encode('utf8')
        if index < last:
            out += token(seed, coord, index)
    return bytes(out)


def expected(doc):
    seed = doc['seed']
    cases = []
    for index, case in enumerate(doc['cases']):
        rows = []
        for j, frame in enumerate(case['frames']):
            kind = frame['Type']
            if kind == 'headers':
                if 'headers_kv' in frame:
                    pairs = list(frame['headers_kv'].items())
                else:
                    pairs = [list(p) for p in frame['data_to_transfered']]
                compiled = []
                for pair_index, (k, v) in enumerate(pairs):
                    compiled.append((
                        resolve(k, seed, 'case/%d/frame/%d/h/%d/n' % (index, j, pair_index)),
                        resolve(v, seed, 'case/%d/frame/%d/h/%d/v' % (index, j, pair_index))))
                rows.append({'Type': 'headers', 'data_to_transfered': compiled,
                             'End_Stream': frame.get('End_Stream', False)})
            elif kind == 'sleep':
                rows.append({'Type': 'sleep', 'Time_to_Stop': frame['Time_to_Stop']})
            else:
                rows.append({'Type': kind,
                             'data_to_transfered': resolve(frame['data_to_transfered'], seed,
                                                           'case/%d/frame/%d/data' % (index, j)),
                             'End_Stream': frame.get('End_Stream', True)})
        cases.append({'name': case['name'], 'frames': rows})
    events = []
    for index, ev in enumerate(doc['events']):
        row = {'kind': ev['kind'], 'at': ev['at']}
        if ev['kind'] == 'headers':
            row['stream'] = ev['stream']
            row['end'] = ev['end']
            row['fields'] = []
            for pair_index, pair in enumerate(ev['fields']):
                row['fields'].append((
                    resolve(pair[0], seed, 'event/%d/h/%d/n' % (index, pair_index)),
                    resolve(pair[1], seed, 'event/%d/h/%d/v' % (index, pair_index))))
        elif ev['kind'] == 'data':
            row['stream'] = ev['stream']
            row['end'] = ev['end']
            row['data'] = resolve(ev['data'], seed, 'event/%d/data' % index)
        events.append(row)
    replayed = simulate(cases, events, doc['timeout_ms'])
    records = []
    for row in replayed:
        sent = b''.join(base.action(t, row['stream'], k, d, e) for t, k, d, e in row['sent'])
        received = b''.join(base.action(t, row['stream'], k, d, e) for t, k, d, e in row['received'])
        body = b''.join(row['body'])
        records.append({'name': row['name'], 'stream': row['stream'], 'state': row['state'],
                        'at': row['at'], 'frames': row['frames'],
                        'request_frames': row['request_frames'],
                        'payload_bytes': row['payload_bytes'], 'sent': base.fp(sent),
                        'received': base.fp(received), 'response_frames': row['response_frames'],
                        'response_body': base.fp(body), 'origin_count': 0, 'flags': []})
    channels_out = []
    owner_seen = {}
    origin = {c['name']: 0 for c in doc['cases']}
    case_flags = {c['name']: set() for c in doc['cases']}
    request_frames = {c['name']: r['request_frames'] for c, r in zip(doc['cases'], records)}
    expect = {c['name']: c['expect'] for c in doc['cases']}
    for ci, channel in enumerate(doc['channels']):
        labels = [p['case'] for p in channel['parts']]
        chunks = [resolve(p['data'], seed, 'channel/%d/part/%d/data' % (ci, pi))
                  for pi, p in enumerate(channel['parts'])]
        data = b''.join(chunks)
        bounds = [0]
        for chunk in chunks:
            bounds.append(bounds[-1] + len(chunk))
        reqs, error = refhttp.parse(data)
        ends = [r['end'] for r in reqs]
        committed = [sum(1 for e in ends if e <= b) for b in bounds[1:]]
        out_reqs = []
        for r in reqs:
            segs = []
            for j in range(len(chunks)):
                low = max(r['start'], bounds[j])
                high = min(r['end'], bounds[j + 1])
                if high > low:
                    if segs and segs[-1][0] == labels[j]:
                        segs[-1][1] += high - low
                    else:
                        segs.append([labels[j], high - low])
            owner = None
            for j in range(len(chunks)):
                if bounds[j] <= r['start'] < bounds[j + 1]:
                    owner = labels[j]
                    break
            flags = set()
            if owner is None:
                flags.add('unattributed')
            if any(label != owner for label, _ in segs):
                flags.add('mixed_owner')
            if r['host_count'] == 0:
                flags.add('missing_host')
            elif r['host_count'] > 1:
                flags.add('multiple_host')
            if owner is not None:
                exp = expect[owner]
                if (r['method'] != exp['method'].encode()
                        or r['target'] != exp['target'].encode()
                        or r['host_count'] != 1
                        or r['host'].lower() != exp['host'].encode().lower()):
                    flags.add('identity')
                owner_seen[owner] = owner_seen.get(owner, 0) + 1
                if owner_seen[owner] > 1:
                    flags.add('extra')
                if request_frames[owner] == 0:
                    flags.add('unsent')
                origin[owner] += 1
                if 'identity' in flags:
                    case_flags[owner].add('identity')
                if 'mixed_owner' in flags:
                    case_flags[owner].add('mixed_origin')
            out_reqs.append({'start': r['start'], 'end': r['end'], 'method': base.fp(r['method']),
                             'target': base.fp(r['target']), 'host': base.fp(r['host']),
                             'host_count': r['host_count'], 'headers': base.field_fp(r['fields']),
                             'body': base.fp(r['body']), 'trailers': base.field_fp(r['trailers']),
                             'framing': r['framing'], 'owner': owner, 'owners': segs,
                             'flags': sorted(flags)})
        channels_out.append({'name': channel['name'], 'bytes': base.fp(data),
                             'requests': out_reqs, 'committed': committed, 'error': error})
    for case, record in zip(doc['cases'], records):
        name = case['name']
        count = origin[name]
        flags = set(case_flags[name])
        if record['request_frames'] > 0 and count == 0:
            flags.add('missing_origin')
        if count > 1:
            flags.add('extra_origin')
        if count > 0 and record['request_frames'] == 0:
            flags.add('unsent_origin')
        record['origin_count'] = count
        record['flags'] = sorted(flags)
    return {'cases': records, 'channels': channels_out}


def gen(rng):
    doc = base.gen_document(rng)
    for channel in doc['channels']:
        for part in channel['parts']:
            roll = rng.random()
            if roll < 0.3:
                part['data'] = '{{ ' + pybytes(part['data'].encode('ascii')) + ' }}'
            elif roll < 0.45:
                part['data'] = part['data'] + '<<random_string>>'
            elif roll < 0.55:
                part['data'] = '<<random_string>>' + part['data']
    for case in doc['cases']:
        for frame in case['frames']:
            if frame['Type'] in ('data', 'datagram') and rng.random() < 0.4:
                frame['data_to_transfered'] = '{{ ' + pybytes(frame['data_to_transfered'].encode('ascii')) + ' }}'
            elif frame['Type'] in ('data', 'datagram') and rng.random() < 0.3:
                frame['data_to_transfered'] = frame['data_to_transfered'] + '<<random_string>>'
    for ev in doc['events']:
        if ev['kind'] == 'data' and rng.random() < 0.4:
            ev['data'] = '{{ ' + pybytes(ev['data'].encode('ascii')) + ' }}'
        elif ev['kind'] == 'data' and rng.random() < 0.3:
            ev['data'] = ev['data'] + '<<random_string>>'
    return doc


def main():
    rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
    trials = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    bad = 0
    for trial in range(trials):
        doc = gen(rng)
        raw = json.dumps(doc).encode('utf8')
        proc = subprocess.run(PROG, input=raw, capture_output=True, cwd='/workspace/project')
        if proc.returncode != 0:
            print('EXIT', proc.returncode, proc.stderr.decode()[:400]); bad += 1; continue
        got = json.loads(proc.stdout.decode('utf8'))
        if base.canonical(got) != base.canonical(expected(doc)):
            bad += 1
            print('MISMATCH trial', trial)
            print('INPUT', json.dumps(doc))
            print('GOT  ', base.canonical(got)[:1200])
            print('WANT ', base.canonical(expected(doc))[:1200])
            if bad >= 2:
                break
    print('trials', trials, 'bad', bad)
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
